(65, 11, 'Liquidación de pago de modalidad', 'liquidacion_pago', 'file', NULL, 1, '<p>Suba la liquidación generada del pago de modalidad en formato <strong>PDF</strong> (máx. 5 MB). El documento debe incluir la marca de agua correspondiente.</p>\n                                    <ul class=\"list-disc mt-2 ml-4\">\n                                        <li class=\"ml-4\">La liquidación debe estar debidamente diligenciada</li>\n                                        <li class=\"ml-4\">Debe contener la marca de agua del banco o entidad</li>\n                                        <li class=\"ml-4\">Asegúrese de que los datos sean legibles</li>\n                                    </ul>', '2026-08-05 14:43:52', '2026-08-05 14:47:04', NULL),
(66, 11, 'Soporte de pago', 'soporte_pago', 'file', NULL, 1, '<p>Suba el soporte de pago de la liquidación en formato <strong>PDF</strong> (máx. 5 MB).</p>\n                                    <ul class=\"list-disc mt-2 ml-4\">\n                                        <li class=\"ml-4\">El soporte debe corresponder a la liquidación adjunta</li>\n                                        <li class=\"ml-4\">Debe ser un comprobante de pago válido</li>\n                                        <li class=\"ml-4\">Asegúrese de que el monto sea el correcto</li>\n                                    </ul>', '2026-08-05 14:43:52', '2026-08-05 14:47:04', NULL),
