(3572, 150, 17, 'Desarrollo de una solución inteligente para la administración\r\nde inventarios con soporte conversacional y reportes analíticos.', '2025-09-03 20:01:44', '2025-09-03 20:01:44', NULL),
(3573, 150, 18, 'Desarrollar un prototipo de software administrativo que integre un módulo de análisis\r\nexploratorio de datos (EDA) y un asistente virtual financiero, orientado a optimizar la\r\ngestión de inventarios, mejorar la toma de decisiones estratégicas y aumentar la\r\ncompetitividad de las micro y pequeñas empresas de la región de Santander.', '2025-09-03 20:01:44', '2025-09-03 20:01:44', NULL),
(3574, 150, 19, '1', '2025-09-03 20:01:44', '2025-09-03 20:01:44', NULL),
(3575, 150, 20, 'Desarrollo de un prototipo de software administrativo que integre un módulo de análisis exploratorio de datos (EDA) y un asistente virtual financiero con interfaz conversacional. Esta solución permitirá a las micro y pequeñas empresas poder optimizar la gestión de inventarios, generar reportes estratégicos y anticipar tendencias de mercado, facilitando la toma de decisiones basadas en datos y fortaleciendo su competitividad.', '2025-09-03 20:01:44', '2025-09-03 20:01:44', NULL),
