(4210, 261, 21, '[\"68c2e1b4ee3b0_1757602228.pdf\",\"68c2e1b4f0c2a_1757602228.pdf\"]', '2025-09-11 14:50:28', '2025-09-11 14:50:28', NULL),
(4211, 250, 15, 'false', '2025-09-11 14:55:16', '2025-09-17 11:15:16', '2025-09-17 11:15:16'),
(4212, 250, 17, 'Desarrollo de un prototipo de intranet para la gestión de la información y comunicación en el programa de Tecnología de desarrollo de sistemas informáticos de las unidades tecnológicas de Santander.', '2025-09-11 14:55:16', '2025-09-17 11:15:16', '2025-09-17 11:15:16'),
(4213, 250, 18, 'Desarrollar un prototipo de intranet para el programa de tecnología de desarrollo de sistemas informáticos de las unidades tecnológicas de Santander para que permita a la comunidad educativa (administrativos, docentes y estudiantes) consultar y publicar información que sea de interés y relevante.', '2025-09-11 14:55:16', '2025-09-17 11:15:16', '2025-09-17 11:15:16'),
(4214, 250, 19, '1', '2025-09-11 14:55:16', '2025-09-17 11:15:16', '2025-09-17 11:15:16'),
(4215, 250, 20, 'En el programa de tecnología de desarrollo de sistemas informáticos de las unidades tecnológicas de santander carece de un sistemas propio y privado que gestione la consulta y publicación de información de interés para la comunidad educativa. En su lugar usa métodos tradicionales como redes sociales y el voz a voz los cuales no son los más eficientes.\r\nEl prototipo plantea tener un sistema de gestión de usuarios y funcionalidades, este tendrá un sistema para que la comunidad educativa publique información como noticias institucionales, documentos de interés, contenido de semilleros, directorio de contactos, PQRS para el programa y anuncios para la comunidad educativa.', '2025-09-11 14:55:16', '2025-09-17 11:15:16', '2025-09-17 11:15:16'),
