(4840, 229, 17, 'Desarrollo de una Aplicación móvil para la generación automática de evaluaciones desde documentos PDF para docentes universitarios de la UTS (2025)', '2025-09-23 18:42:16', '2025-09-23 18:42:16', NULL),
(4841, 229, 18, 'Implementar una aplicación que analice documentos PDF y/o texto y genere automáticamente preguntas (opción múltiple, verdadero/falso y completar) con niveles de dificultad variables, exportables y editables por el docente.', '2025-09-23 18:42:16', '2025-09-23 18:42:16', NULL),
(4842, 229, 19, '1', '2025-09-23 18:42:16', '2025-09-23 18:42:16', NULL),
(4843, 229, 20, 'Aplicación móvil que extrae y procesa texto de documentos PDF para generar automáticamente evaluaciones educativas (preguntas de opción múltiple, verdadero/falso y completar) con niveles de dificultad variables. La herramienta está dirigida a docentes universitarios de la UTS y busca reducir el tiempo de diseño de pruebas, crear bancos de preguntas reutilizables y facilitar la evaluación formativa. El sistema combinará extracción de texto, técnicas básicas de NLP y algoritmos de generación y ranking de distractores, integrados en una interfaz móvil intuitiva y un servicio backend escalable.', '2025-09-23 18:42:16', '2025-09-23 18:42:16', NULL),
