INSERT INTO `valores_campos` (`id`, `solicitud_id`, `campo_id`, `valor`, `created_at`, `updated_at`, `deleted_at`) VALUES
(5009, 278, 20, 'El objetivo del presente proyecto es desarrollar un videojuego educativo al kit de robótica Thames & Kosmos donde nos permita enriquecer el aprendizaje practico. Dicho videojuego nos permite seguir interactivamente las diferentes instrucciones para la construcción de cada robot del kit, encontraremos el código de programación de cada robot, el respectivo funcionamiento del robot y encontraremos el video del funcionamiento de cada robot mediante el código de programación. Incorporando recursos tecnológicos que promueven el aprendizaje significativo en ciencia, tecnología, ingeniería y matemáticas, buscando fomentar la comprensión, motivación y independencia de los participantes.', '2025-09-24 20:25:37', '2025-09-24 21:09:26', '2025-09-24 21:09:26'),
(5010, 278, 22, 'NULL', '2025-09-24 20:25:37', '2025-09-24 21:09:26', '2025-09-24 21:09:26'),
