(5283, 212, 15, 'false', '2025-09-26 22:43:15', '2025-09-26 23:03:48', '2025-09-26 23:03:48'),
(5284, 212, 17, 'Sistema Inteligente para la Simulación y Predicción de Terremotos con Generación de Rutas de\r\nEvacuación en Bucaramanga.', '2025-09-26 22:43:15', '2025-09-26 23:03:48', '2025-09-26 23:03:48'),
(5285, 212, 18, 'Implementar un sistema inteligente que simule y prediga el impacto de terremotos en\r\nBucaramanga, Santander.', '2025-09-26 22:43:15', '2025-09-26 23:03:48', '2025-09-26 23:03:48'),
(5286, 212, 19, '1', '2025-09-26 22:43:15', '2025-09-26 23:03:48', '2025-09-26 23:03:48'),
(5287, 212, 20, 'La propuesta consiste en implementar un sistema inteligente que permita simular terremotos en\r\nel área de Bucaramanga, considerando parámetros como intensidad, duración y profundidad. El\r\nsistema tendrá como finalidad predecir, mediante modelos de machine learning, la afectación que\r\nestos eventos podrían generar en diferentes zonas de la ciudad y, a partir de ello, brindar apoyo\r\nen la planificación de estrategias de gestión del riesgo y toma de decisiones. Además, el sistema\r\nintegrará la generación de rutas de evacuación dinámicas, con el fin de orientar a la población\r\nhacia zonas seguras durante un evento sísmico.', '2025-09-26 22:43:15', '2025-09-26 23:03:48', '2025-09-26 23:03:48'),
(5288, 212, 22, 'NULL', '2025-09-26 22:43:15', '2025-09-26 23:03:48', '2025-09-26 23:03:48'),
(5289, 212, 23, 'NULL', '2025-09-26 22:43:15', '2025-09-26 23:03:48', '2025-09-26 23:03:48'),
