(5332, 269, 15, 'false', '2025-09-27 00:22:47', '2025-09-27 00:22:47', NULL),
(5333, 269, 17, 'Sistema de predicción del rendimiento académico de estudiantes mediante técnicas de minería de datos e inteligencia artificial.', '2025-09-27 00:22:47', '2025-09-27 00:22:47', NULL),
(5334, 269, 18, 'Desarrollar un modelo de predicción del rendimiento académico de estudiantes utilizando técnicas de minería de datos e inteligencia artificial.', '2025-09-27 00:22:47', '2025-09-27 00:22:47', NULL),
(5335, 269, 19, '4', '2025-09-27 00:22:47', '2025-09-27 00:22:47', NULL),
(5336, 269, 20, 'La idea propuesta consiste en un modelo predictivo que mediante el uso de técnicas de minería de datos e inteligencia artificial nos permita anticipar el rendimiento académico de los estudiantes a partir de variables y/o factores asociados al aprendizaje. El fin de esta propuesta es identificar patrones para que las instituciones educativas puedan detectar tempranamente a los estudiantes en riesgo académico y poder implementar estrategias de apoyo para así contribuir a la mejora de la calidad educativa.', '2025-09-27 00:22:47', '2025-09-27 00:22:47', NULL),
(5337, 269, 22, '125-2025-052', '2025-09-27 00:22:47', '2025-10-02 21:05:53', NULL),
(5338, 269, 23, '64', '2025-09-27 00:22:47', '2025-10-02 21:05:53', NULL),
