(9307, 495, 15, 'false', '2026-02-22 21:32:50', '2026-02-22 21:32:50', NULL),
(9308, 495, 17, 'Asistente Inteligente para la Gestión Automatizada de Inventario en una Empresa Agropecuaria.', '2026-02-22 21:32:50', '2026-02-22 21:32:50', NULL),
(9309, 495, 18, 'Desarrollar un asistente inteligente basado en inteligencia artificial para la gestión automatizada de inventarios en empresas del sector agropecuario, integrando procesamiento de lenguaje natural y análisis predictivo para optimizar la toma de decisiones estratégicas en el control, rotación y reposición de insumos y productos.', '2026-02-22 21:32:50', '2026-02-22 21:32:50', NULL),
(9310, 495, 19, '1', '2026-02-22 21:32:50', '2026-02-22 21:32:50', NULL),
