INSERT INTO `valores_campos` (`id`, `solicitud_id`, `campo_id`, `valor`, `created_at`, `updated_at`, `deleted_at`) VALUES
(9408, 455, 18, 'Desarrollar una aplicación móvil que\r\nfacilite el cuidado y organización de las\r\nmascotas mediante funciones de registro,\r\nrecordatorios y acceso rápido a\r\ninformación esencial, mejorando la\r\nexperiencia del usuario y el bienestar del\r\nanimal.', '2026-02-24 18:14:34', '2026-03-03 18:37:55', '2026-03-03 18:37:55'),
(9409, 455, 19, '1', '2026-02-24 18:14:34', '2026-03-03 18:37:55', '2026-03-03 18:37:55'),
(9410, 455, 20, 'En el área metropolitana Bucaramanga se presenta ciertos problemas  con las veterinarias y los usuarios de las mascotas, donde no tiene un supervisión en la agenda, bienestar, historial clínico y  cuidado.\r\nes una plataforma móvil diseñada para conectar con el cuidado diario de las mascotas con la supervisión de un profesional veterinario, la app que en esta caso le colocamos como nombre (Little paws) va tener los siguientes requerimientos para el funcionamiento de aquella,\r\n2 roles que en este caso son: usuario y veterinario.\r\nRegistro de Usuarios: Creación de cuentas nuevas con correo y contraseña.\r\nInicio de Sesión (Login): Validación de credenciales para entrar a la app.\r\nPerfil de usuario: cada usuario va a tener un perfil donde subir su información y la del a mascota.\r\ncitas de vacunación programadas ya sea domiciliarias en la veterinaria .\r\ncarnet de vacunación digital en el perfil con la opción de cargar en pdf,\r\nchatbot para preguntas del usuario sobre la mascota o asuntos veterinarios,\r\ncitas de cuidado de higiene.\r\nnotificaciones.\r\ncitas de vacunas.\r\nhistorial clínico.\r\n rol de veterinario tiene opciones de ver citas, mascotas, historial clínico, agendar citas etc.\r\nbase de datos con la información.\r\nprácticamente la app es un sistema de gestión de veterinarias donde se va a llevar acabo la información del usuario y  de la veterinaria en este caso el doctor veterinario que este registrado en el sistema.', '2026-02-24 18:14:34', '2026-03-03 18:37:55', '2026-03-03 18:37:55'),
(9411, 455, 22, 'NULL', '2026-02-24 18:14:34', '2026-03-03 18:37:55', '2026-03-03 18:37:55'),
