(18807, 874, 15, 'false', '2026-08-30 21:34:05', '2026-08-30 21:34:05', NULL),
(18808, 874, 17, 'Desarrollo de una plataforma inteligente para la optimización operativa de establecimientos gastronómicos mediante visión computacional, inteligencia artificial y análisis predictivo.', '2026-08-30 21:34:05', '2026-08-30 21:34:05', NULL),
(18809, 874, 18, 'Desarrollar una plataforma inteligente para la optimización operativa de pequeños y medianos establecimientos gastronómicos mediante la integración de visión computacional, inteligencia artificial y comunicación en tiempo real, permitiendo analizar el comportamiento del servicio, automatizar procesos de gestión, predecir necesidades del negocio y generar recomendaciones que mejoren la eficiencia operativa, la experiencia del cliente y la toma de decisiones.', '2026-08-30 21:34:05', '2026-08-30 21:34:05', NULL),
(18810, 874, 19, '4', '2026-08-30 21:34:05', '2026-08-30 21:34:05', NULL);
INSERT INTO `valores_campos` (`id`, `solicitud_id`, `campo_id`, `valor`, `created_at`, `updated_at`, `deleted_at`) VALUES
(18811, 874, 20, 'La propuesta consiste en desarrollar una plataforma inteligente orientada a pequeños y medianos establecimientos gastronómicos que permita transformar la operación tradicional mediante el uso de inteligencia artificial, visión computacional y análisis de datos. La solución utilizará tecnologías como OpenCV y el modelo YOLO para analizar la ocupación de mesas, flujo de clientes y tiempos de atención, generando información útil sobre el desempeño del servicio. Además, incorporará herramientas inteligentes para automatizar pedidos mediante canales digitales, analizar patrones de consumo, predecir la demanda y generar recomendaciones para la gestión del inventario. A diferencia de los sistemas convencionales de administración gastronómica, la plataforma no solo registra información, sino que la interpreta para proporcionar decisiones estratégicas que permitan mejorar la eficiencia del establecimiento, reducir pérdidas y ofrecer una experiencia más personalizada al cliente.', '2026-08-30 21:34:05', '2026-08-30 21:34:05', NULL),
(18812, 874, 22, 'NULL', '2026-08-30 21:34:05', '2026-08-30 21:34:05', NULL),
