(19268, 956, 17, 'Desarrollo de un sistema web para la radicación, clasificación automática y control de términos legales de pqrsd en entidades públicas de colombia.', '2026-09-02 12:38:39', '2026-09-02 12:38:39', NULL),
(19269, 956, 18, 'Desarrollar un sistema web que permita la radicación, clasificación automática y seguimiento de peticiones, quejas, reclamos, sugerencias y denuncias, con control de los términos legales mediante técnicas de procesamiento de lenguaje natural.', '2026-09-02 12:38:39', '2026-09-02 12:38:39', NULL),
(19270, 956, 19, '1', '2026-09-02 12:38:39', '2026-09-02 12:38:39', NULL),
(19271, 956, 20, 'Desarrollar un sistema web orientado a entidades públicas que permita la radicación, clasificación automática y seguimiento de las Peticiones, Quejas, Reclamos, Sugerencias y Denuncias (PQRSDF). El sistema incorporará técnicas de procesamiento de lenguaje natural para apoyar la clasificación de las solicitudes y contará con un mecanismo de control y seguimiento de los términos legales de respuesta, facilitando una gestión más eficiente, organizada y oportuna de los requerimientos ciudadanos.', '2026-09-02 12:38:39', '2026-09-02 12:38:39', NULL),
